#### 1. `sudoku_board.py`

This file will define the `SudokuBoard` class, which represents the 9x9 grid of the Sudoku puzzle.

```python
# sudoku_board.py

'''

This class represents the 9x9 grid of the Sudoku puzzle.
'''

class SudokuBoard:
    def __init__(self):
        self.board = [[0 for _ in range(9)] for _ in range(9)]

    def is_valid(self, row, col, num):
        # Check if the number is not already in the row
        for x in range(9):
            if self.board[row][x] == num:
                return False

        # Check if the number is not already in the column
        for x in range(9):
            if self.board[x][col] == num:
                return False

        # Check if the number is not already in the 3x3 subgrid
        start_row, start_col = 3 * (row // 3), 3 * (col // 3)
        for i in range(3):
            for j in range(3):
                if self.board[i + start_row][j + start_col] == num:
                    return False

        return True

    def solve(self):
        empty = self.find_empty()
        if not empty:
            return True
        row, col = empty

        for num in range(1, 10):
            if self.is_valid(row, col, num):
                self.board[row][col] = num

                if self.solve():
                    return True

                self.board[row][col] = 0

        return False

    def find_empty(self):
        for i in range(9):
            for j in range(9):
                if self.board[i][j] == 0:
                    return (i, j)
        return None

    def print_board(self):
        for row in self.board:
            print(" ".join(str(num) if num != 0 else '.' for num in row))
```

#### 2. `game_logic.py`

This file will define the `GameLogic` class, which contains the logic to check if the puzzle is valid, if a move is correct, and if the puzzle is solved.

```python
# game_logic.py

'''

This class contains the logic to check if the puzzle is valid, if a move is correct, and if the puzzle is solved.
'''

from sudoku_board import SudokuBoard

class GameLogic:
    def __init__(self):
        self.board = SudokuBoard()

    def is_valid_move(self, row, col, num):
        return self.board.is_valid(row, col, num)

    def solve_puzzle(self):
        return self.board.solve()

    def get_board(self):
        return self.board.board
```

#### 3. `gui.py`

This file will define the `GUI` class, which handles the graphical user interface, allowing the player to interact with the Sudoku board.

```python
# gui.py

'''

This class handles the graphical user interface, allowing the player to interact with the Sudoku board.
'''

import tkinter as tk
from tkinter import messagebox
from game_logic import GameLogic

class GUI:
    def __init__(self):
        self.root = tk.Tk()
        self.root.title("Sudoku Game")
        self.game_logic = GameLogic()
        self.buttons = [[None for _ in range(9)] for _ in range(9)]
        self.create_board()
        self.root.mainloop()

    def create_board(self):
        for row in range(9):
            for col in range(9):
                button = tk.Button(self.root, text="", width=5, height=2, command=lambda r=row, c=col: self.on_button_click(r, c))
                button.grid(row=row, column=col)
                self.buttons[row][col] = button

    def on_button_click(self, row, col):
        value = self.buttons[row][col].get()
        if value.isdigit() and 1 <= int(value) <= 9:
            if self.game_logic.is_valid_move(row, col, int(value)):
                self.buttons[row][col].config(text=value)
                if self.game_logic.solve_puzzle():
                    messagebox.showinfo("Congratulations", "You solved the puzzle!")
            else:
                messagebox.showerror("Error", "Invalid move")

if __name__ == "__main__":
    GUI()
```

